AND room_type = #{query.roomType}
AND monthly_rent >= #{query.minRent}
AND monthly_rent <= #{query.maxRent}
AND rating >= #{query.minRating}

    AND (community_name LIKE #{query.keywordPattern} ESCAPE '!'
